class Solution:
    def kthSmallest(self, mat: list[list[int]], k: int) -> int:
        sums = [0]
        for row in mat:
            new_sums = []
            for s in sums:
                for x in row:
                    new_sums.append(s + x)
            sums = new_sums
        sums.sort()
        return sums[k - 1]

