class Solution:
    def kthSmallest(self, mat: list[list[int]], k: int) -> int:
        sums = [0]
        for row in mat:
            merged = []
            for s in sums:
                for x in row:
                    merged.append(s + x)
            merged.sort()
            sums = merged[:k]
        return sums[k - 1]

