class Solution:
    def kthSmallest(self, mat: list[list[int]], k: int) -> int:
        import heapq
        m = len(mat)
        start = tuple([0] * m)
        start_sum = sum(row[0] for row in mat)
        heap = [(start_sum, start)]
        seen = {start}
        ans = start_sum
        for _ in range(k):
            ans, state = heapq.heappop(heap)
            for r in range(m):
                c = state[r]
                if c + 1 < len(mat[r]):
                    nxt = list(state)
                    nxt[r] += 1
                    nxt = tuple(nxt)
                    if nxt not in seen:
                        seen.add(nxt)
                        ns = ans - mat[r][c] + mat[r][c + 1]
                        heapq.heappush(heap, (ns, nxt))
        return ans

